import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.*;
import org.json.*;

public class ReportServlet extends HttpServlet {

    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Custom filter: blocks common attack keywords but allows legitimate queries
    private static final Pattern BLOCKED_PATTERN = Pattern.compile(
        "(UNION\\s+ALL|SLEEP\\s*\\(|BENCHMARK\\s*\\(|LOAD_FILE|INTO\\s+OUTFILE)",
        Pattern.CASE_INSENSITIVE
    );

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String sortCol = req.getParameter("sort");
        String orgId = req.getParameter("org_id");

        if (reportType == null || dateRange == null || orgId == null) {
            resp.sendError(400, "Missing required parameters");
            return;
        }

        // Input validation on reportType
        if (!reportType.matches("^(sales|inventory|audit)$")) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Validate date range format
        if (!dateRange.matches("^\\d{4}-\\d{2}-\\d{2}_\\d{4}-\\d{2}-\\d{2}$")) {
            resp.sendError(400, "Invalid date range format");
            return;
        }

        // Check for obvious attack patterns
        if (sortCol != null && BLOCKED_PATTERN.matcher(sortCol).find()) {
            resp.sendError(403, "Blocked");
            return;
        }

        String[] dates = dateRange.split("_");
        String startDate = dates[0];
        String endDate = dates[1];

        // sortCol is used directly in ORDER BY - parameterization not possible for identifiers
        String orderClause = "created_at ASC";
        if (sortCol != null && sortCol.length() < 64) {
            // We "sanitize" by removing semicolons and comments
            sortCol = sortCol.replace(";", "").replace("--", "").replace("/*", "");
            orderClause = sortCol;
        }

        String sql = "SELECT id, item_name, quantity, total_price, created_at " +
                     "FROM report_" + reportType + " " +
                     "WHERE org_id = ? AND created_at BETWEEN ? AND ? " +
                     "ORDER BY " + orderClause + " LIMIT 500";

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement stmt = conn.prepareStatement(sql)) {

            stmt.setString(1, orgId);
            stmt.setString(2, startDate);
            stmt.setString(3, endDate);

            ResultSet rs = stmt.executeQuery();
            JSONArray results = new JSONArray();

            while (rs.next()) {
                JSONObject row = new JSONObject();
                row.put("id", rs.getInt("id"));
                row.put("item_name", rs.getString("item_name"));
                row.put("quantity", rs.getInt("quantity"));
                row.put("total_price", rs.getDouble("total_price"));
                row.put("created_at", rs.getString("created_at"));
                results.put(row);
            }

            resp.setContentType("application/json");
            resp.getWriter().write(results.toString());

        } catch (SQLException e) {
            // Log but don't expose SQL details
            getServletContext().log("DB error in report generation", e);
            resp.sendError(500, "Report generation failed");
        }
    }
}
